create table public.collection_stores (store_id uuid default gen_random_uuid() not null,platform text default 'shopee'::text not null,store_key text not null,store_url text not null,display_name text not null,first_added_at timestamp with time zone default now() not null,last_scan_id uuid,last_scan_started_at timestamp with time zone,last_scan_finished_at timestamp with time zone,last_scan_status text,last_discovered integer default 0 not null,last_newly_queued integer default 0 not null,last_duplicate integer default 0 not null,last_already_tracked integer default 0 not null,updated_at timestamp with time zone default now() not null,last_sold_out integer default 0 not null,last_pages_current integer default 0 not null,last_pages_total integer default 0 not null);
create table public.collector_backlog_products (backlog_id uuid not null,product_id bigint not null,completed_at timestamp with time zone,outcome text);
create table public.collector_backlogs (id uuid default gen_random_uuid() not null,created_at timestamp with time zone default now() not null,finished_at timestamp with time zone);
create table public.personal_collection_products (product_id bigint not null,added_at timestamp with time zone default now() not null,next_check_at timestamp with time zone default now() not null,lease_until timestamp with time zone);
create table public.price_observations (id bigint generated always as identity not null,variation_id bigint not null,observed_date date not null,observed_at timestamp with time zone default now() not null,price numeric(14,2) not null,original_price numeric(14,2),discount_percent numeric(5,2),is_in_stock boolean default true not null,source text default 'extension'::text not null,metadata jsonb default '{}'::jsonb not null,created_at timestamp with time zone default now() not null);
create table public.product_daily_checks (id bigint generated by default as identity not null,product_id bigint not null,checked_date date not null,checked_at timestamp with time zone default now() not null,source text not null,status text not null,variation_count integer default 0 not null,changed_count integer default 0 not null,unchanged_count integer default 0 not null,failed_count integer default 0 not null,metadata jsonb default '{}'::jsonb not null,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null);
create table public.product_daily_extension_visits (product_id bigint not null,client_hash text not null,visited_date date not null,first_visited_at timestamp with time zone not null);
create table public.product_variations (id bigint generated always as identity not null,product_id bigint not null,external_variation_id text not null,name text default 'Default'::text not null,sku text,is_active boolean default true not null,metadata jsonb default '{}'::jsonb not null,first_seen_at timestamp with time zone default now() not null,last_seen_at timestamp with time zone default now() not null,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null);
create table public.products (id bigint generated always as identity not null,platform text not null,external_shop_id text not null,external_product_id text not null,product_url text not null,name text not null,shop_name text,image_url text,currency text default 'PHP'::text not null,is_active boolean default true not null,metadata jsonb default '{}'::jsonb not null,first_seen_at timestamp with time zone default now() not null,last_seen_at timestamp with time zone default now() not null,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null,tracking_enabled boolean default true not null,next_check_at timestamp with time zone,last_check_attempt_at timestamp with time zone,last_checked_at timestamp with time zone,last_check_status text,consecutive_check_failures integer default 0 not null,check_lease_until timestamp with time zone,all_variations_sold_out boolean default false not null,stock_status_checked_at timestamp with time zone,consecutive_sold_out_checks integer default 0 not null,total_sold bigint,review_count bigint,favorite_count bigint,rating numeric(4,3),price_drop_at timestamp with time zone,activity_observed_at timestamp with time zone,collector_page_outcome text,consecutive_unavailable_checks integer default 0 not null,consecutive_page_errors integer default 0 not null,shopee_sales_activity text);
create table public.public_collection_request_quotas (requester_hash text not null,requested_date date not null,request_count integer default 0 not null,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null);
create table public.public_collection_requests (request_id uuid default gen_random_uuid() not null,platform text default 'shopee'::text not null,external_shop_id text not null,external_product_id text not null,product_url text not null,requested_at timestamp with time zone default now() not null,status text default 'pending'::text not null,lease_until timestamp with time zone,attempt_count integer default 0 not null,completed_at timestamp with time zone,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null,eligible_at timestamp with time zone default now() not null,collector_page_outcome text,consecutive_unavailable_checks integer default 0 not null,consecutive_page_errors integer default 0 not null,consecutive_sold_out_checks integer default 0 not null,one_time boolean default false not null);
create table public.site_settings (key text not null,boolean_value boolean default false not null,updated_at timestamp with time zone default now() not null);
create table public.store_collection_requests (request_id uuid default gen_random_uuid() not null,store_id uuid not null,platform text default 'shopee'::text not null,external_shop_id text not null,external_product_id text not null,product_url text not null,last_seen_at timestamp with time zone default now() not null,status text default 'pending'::text not null,lease_until timestamp with time zone,attempt_count integer default 0 not null,completed_at timestamp with time zone,updated_at timestamp with time zone default now() not null,discovered_sold_out boolean default false not null,eligible_at timestamp with time zone default now() not null,collector_page_outcome text,consecutive_unavailable_checks integer default 0 not null,consecutive_page_errors integer default 0 not null,consecutive_sold_out_checks integer default 0 not null);
create table public.store_scan_discoveries (scan_id uuid not null,external_shop_id text not null,external_product_id text not null,sold_out boolean default false not null);
create table public.store_scan_history (scan_id uuid not null,store_id uuid not null,started_at timestamp with time zone default now() not null,finished_at timestamp with time zone,status text default 'incomplete'::text not null,discovered integer default 0 not null,newly_queued integer default 0 not null,duplicate integer default 0 not null,already_tracked integer default 0 not null,sold_out integer default 0 not null,pages_current integer default 0 not null,pages_total integer default 0 not null);
